private static @Nullable Object messageValueFromFieldValue(SchemaInformation schemaInformation,FieldDescriptor fieldDescriptor,@Nullable Object bqValue,boolean ignoreUnknownValues) throws SchemaConversionException {
  if (bqValue == null) {
    if (fieldDescriptor.isOptional()) {
      return null;
    }
 else     if (fieldDescriptor.isRepeated()) {
      return Collections.emptyList();
    }
 else {
      throw new SchemaDoesntMatchException("Received null value for non-nullable field " + schemaInformation.getFullName());
    }
  }
  if (fieldDescriptor.isRepeated()) {
    List<Object> listValue=(List<Object>)bqValue;
    List<@Nullable Object> protoList=Lists.newArrayListWithCapacity(listValue.size());
    for (    @Nullable Object o : listValue) {
      if (o != null) {
        try {
          protoList.add(singularFieldToProtoValue(schemaInformation,fieldDescriptor,o,ignoreUnknownValues));
        } catch (DateTimeParseException | NumberFormatException e) {
          throw new SchemaConversionException("Failed to convert field value: " + o, e);
        }
      }
    }
    return protoList;
  }
  try {
    return singularFieldToProtoValue(schemaInformation,fieldDescriptor,bqValue,ignoreUnknownValues);
  } catch (DateTimeParseException | NumberFormatException e) {
    throw new SchemaConversionException("Failed to convert field value: " + bqValue, e);
  }
}
